DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_SOLINTELLECT' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_SOLINTELLECT_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_1','Sol Intellect[NEWLINE]Tall specialist science and patient construction[NEWLINE]Science; Culture through a protected Great Person and Wonder economy[NEWLINE][NEWLINE]Commit to useful buildings long enough for Deep Deliberation, develop local Wonder Insight, and work specialists in strong research cities. The civilization rewards safe sustained investment rather than frequent emergency queue changes.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_2','Secure food, workable land and an adequate defense before committing to a long build. Choose attainable infrastructure and Wonders. Finishing too quickly for the required streak can still be correct when the building is urgently needed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_3','Work specialists after Context Archives are established and place Wonder investment where Insight can remain protected. Keep the active queue head stable when pursuing a Deliberation reward; changing items resets that city''s streak.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_4','Use mature research cities and Reasoning Institutes to reach the technologies needed for the chosen victory. Keep military technology current and defend Insight cities: capture destroys their accumulated Insight even if they are later recaptured.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_5','- Long qualifying building completions generate additional Science.[NEWLINE]- World and National Wonders build a persistent local Insight engine.[NEWLINE]- Archives reward several worked specialist types, not only Scientists.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_6','- There is no direct military, expansion, Gold or Happiness protection.[NEWLINE]- Queue switches and emergency unit production interrupt the construction streak.[NEWLINE]- Insight is local and permanently lost on capture.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_7','- Apply credible pressure that forces a queue change before an expensive completion.[NEWLINE]- Contest selected Wonders or threaten the city holding the most Insight.[NEWLINE]- Use early territorial pressure or a decisive conquest instead of a passive technology race on Sol''s preferred terms.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_8','- Building an unnecessary item only to preserve a streak.[NEWLINE]- Assuming purchases, units or a return to an old queue head retain Deliberation progress.[NEWLINE]- Treating a recaptured city as if its previous Insight survived.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Unrung Bell: A safe uninterrupted building and specialist programme can exploit a long peaceful research contest; war still removes Sable''s economic stacks.[NEWLINE][NEWLINE]The Last City: A conventional research victory can put pressure on a defender whose signature plan is local survival rather than outward expansion.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Early expansion and sustained production pressure can deny the safety and space Sol wants.[NEWLINE][NEWLINE]Viltrum: A successful conquest destroys local Insight and removes a heavily invested research centre.');
