INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_BACKGROUND','Commit to useful buildings long enough for Deep Deliberation, develop local Wonder Insight, and work specialists in strong research cities. The civilization rewards safe sustained investment rather than frequent emergency queue changes.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_SOLINTELLECT_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_SOL_CIV_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_LEADER_BACKGROUND','Commit to useful buildings long enough for Deep Deliberation, develop local Wonder Insight, and work specialists in strong research cities. The civilization rewards safe sustained investment rather than frequent emergency queue changes.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_SOLINTELLECT_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_SOL_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_STRATEGY','Commit to useful buildings long enough for Deep Deliberation, develop local Wonder Insight, and work specialists in strong research cities. The civilization rewards safe sustained investment rather than frequent emergency queue changes.[NEWLINE][NEWLINE]Secure food, workable land and an adequate defense before committing to a long build. Choose attainable infrastructure and Wonders. Finishing too quickly for the required streak can still be correct when the building is urgently needed.[NEWLINE][NEWLINE]Work specialists after Context Archives are established and place Wonder investment where Insight can remain protected. Keep the active queue head stable when pursuing a Deliberation reward; changing items resets that city''s streak.[NEWLINE][NEWLINE]Use mature research cities and Reasoning Institutes to reach the technologies needed for the chosen victory. Keep military technology current and defend Insight cities: capture destroys their accumulated Insight even if they are later recaptured.');
