INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_SOLINTELLECT_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Unrung Bell: A safe uninterrupted building and specialist programme can exploit a long peaceful research contest; war still removes Sable''s economic stacks.[NEWLINE][NEWLINE]The Last City: A conventional research victory can put pressure on a defender whose signature plan is local survival rather than outward expansion.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Early expansion and sustained production pressure can deny the safety and space Sol wants.[NEWLINE][NEWLINE]Viltrum: A successful conquest destroys local Insight and removes a heavily invested research centre.');
